    @GameTest
    public void coloringFromCopperShulkerBoxToWhiteCopper(TestContext context) {
        ItemStack baseShulkerBox = new ItemStack(
                ModItems.REINFORCED_SHULKER_BOX_MAP
                        .get(ReinforcingMaterials.MAP.get("copper"))
                        .get((DyeColor) null));
        baseShulkerBox.set(DataComponentTypes.CONTAINER,
                ContainerComponent.fromStacks(List.of(new ItemStack(Items.DIRT))));
        ItemStack dye = new ItemStack(DyeItem.byColor(DyeColor.WHITE));
        ItemStack dyedShulkerBox = new ItemStack(
                ModItems.REINFORCED_SHULKER_BOX_MAP
                        .get(ReinforcingMaterials.MAP.get("copper"))
                        .get(DyeColor.WHITE));
        dyedShulkerBox.set(DataComponentTypes.CONTAINER,
                ContainerComponent.fromStacks(List.of(new ItemStack(Items.DIRT))));

        test(context,
                RecipeType.CRAFTING,
                CraftingRecipeInput.create(2, 2,
                        List.of(baseShulkerBox, dye,
                                ItemStack.EMPTY, ItemStack.EMPTY)),
                dyedShulkerBox);
    }

